import * as React from 'react'
import { cn } from '@/lib/utils'

export interface HeaderStandInProps extends React.HTMLAttributes<HTMLDivElement> {
  /** True while the primary instance is scrolled away and this copy speaks
   * for it. Pass the same value to the child field's `tabbable` (inverted
   * nowhere -- `tabbable={shown}`). A stand-in that holds focus stays open
   * after this goes false, until focus leaves it. */
  shown: boolean
}

/**
 * Header stand-in for a field whose primary instance lives in a scrollable
 * region: grows in via max-width/opacity while the primary is scrolled away
 * (see `useStandInTarget`) and collapses back when it returns -- width rather
 * than mount/unmount, so the nav beside it never jumps. Collapsed it is
 * aria-hidden and click-through, and the child should be untabbable too (its
 * `tabbable={shown}`), since a zero-width field still catches Tab.
 *
 * While focus is inside it, it stays open whatever `shown` says, so a caret
 * never sits in an invisible field. Typing into a search stand-in filters the
 * list its primary sits above, and a list that shrinks below its scroller's
 * height snaps that scroller to the top and brings the primary back into
 * view; without the hold the field in use would collapse under the caret.
 * The hold releases when focus moves out, and the `shown` rule resumes from
 * there. Focus lost to another window does not release it, since the browser
 * hands focus back on return.
 *
 * Owns only the animated wrapper. The responsive gate and the slot in the
 * header row (e.g. `hidden wide:flex flex-1 justify-center min-w-0 px-2`)
 * stay with the app -- the breakpoint the stand-in exists at differs per
 * layout. The collapsed width is an inline style rather than a class, so a
 * caller `className` carrying its own `max-w-*` (the shown width) cannot
 * knock it out through the tailwind-merge. The p-1.5/-m-1.5 pair keeps the
 * clip edge 6px off the child on every side: the focus ring (2px outline at
 * 2px offset) draws outside the child's box and the overflow-hidden the
 * collapse needs would clip it flush; 6px rather than the exact 4px so
 * fractional display scaling never shaves the ring's antialiased edge. The
 * negative margin cancels the padding's footprint, and the collapsed width
 * still nets to zero.
 */
export const HeaderStandIn = React.forwardRef<HTMLDivElement, HeaderStandInProps>(
  ({ shown, className, style, children, ...props }, ref) => {
    const [focused, setFocused] = React.useState(false)
    const open = shown || focused

    const { onFocus, onBlur, ...rest } = props
    const handleFocus = (e: React.FocusEvent<HTMLDivElement>) => {
      setFocused(true)
      onFocus?.(e)
    }
    const handleBlur = (e: React.FocusEvent<HTMLDivElement>) => {
      // Focus moving between the field and its own clear button stays inside;
      // a null target with the document unfocused is the window going away.
      const inside = e.relatedTarget instanceof Node && e.currentTarget.contains(e.relatedTarget)
      if (!inside && (e.relatedTarget !== null || document.hasFocus())) setFocused(false)
      onBlur?.(e)
    }

    return (
      <div
        ref={ref}
        aria-hidden={!open}
        className={cn(
          'w-full overflow-hidden p-1.5 -m-1.5 transition-[max-width,opacity] duration-300 motion-reduce:transition-none',
          'max-w-sm',
          open ? 'opacity-100' : 'opacity-0 pointer-events-none',
          className,
        )}
        style={{ ...style, maxWidth: open ? style?.maxWidth : '0px' }}
        onFocus={handleFocus}
        onBlur={handleBlur}
        {...rest}
      >
        {children}
      </div>
    )
  },
)
HeaderStandIn.displayName = 'HeaderStandIn'
